<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

int main() {
    int P, K;
    cin >> P >> K;
    vector<int> parent(P + 1), rank(P + 1, 1);
    for (int i = 1; i <= P; ++i) parent[i] = i;
    function<int(int)> findp = [&](int x) {
        if (parent[x] != x) parent[x] = findp(parent[x]);
        return parent[x];
    };
    auto union_sets = [&](int a, int b) {
        if (rank[a] >= rank[b]) {
            parent[b] = a;
            ++rank[a];
        } else {
            parent[a] = b;
            ++rank[b];
        }
    };
    for (int i = 1; i <= P; ++i) {
        int val = (long long)K * i % P;
        int pa = findp(i);
        int pb = findp(val);
        if (pa != pb) union_sets(pa, pb);
    }
    set<int> groupSet;
    for (int i = 1; i <= P; ++i) {
        groupSet.insert(findp(i));
    }
    long long ways;
    const long long MOD = 1000000007;
    function<long long(long long, long long, long long)> fast_pow = [&](long long base, long long exp, long long mod) {
        long long res = 1;
        while (exp > 0) {
            if (exp & 1) res = (res * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    };
    if (K == 0) {
        ways = fast_pow(P, P - 1, MOD);
    } else if (K == 1) {
        ways = fast_pow(P, P, MOD);
    } else {
        ways = fast_pow(P, (long long)groupSet.size(), MOD);
    }
    cout << ways << "\n";
    return 0;
}
